import React, { useEffect, useState } from 'react';
import { View, Text, Image, TouchableOpacity, FlatList, StyleSheet, Linking, Dimensions, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { doc, onSnapshot, collection, query, where, updateDoc, arrayUnion, arrayRemove, addDoc, getDoc, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../../config';
import { useTheme, BRAND } from '../../constants/theme';

const W = Dimensions.get('window').width / 3 - 2;

export default function UserProfileScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
    const router = useRouter();
      const { c } = useTheme();
        const myUid = auth.currentUser?.uid || '';
          const [profile, setProfile] = useState<any>(null);
            const [me, setMe] = useState<any>(null);
              const [posts, setPosts] = useState<any[]>([]);

                useEffect(() => {
                    if (!id) return;
                        const u1 = onSnapshot(doc(db, 'users', id), (s) => { if (s.exists()) setProfile(s.data()); });
                            const u2 = onSnapshot(query(collection(db, 'posts'), where('uid', '==', id)), (s) => {
                                  setPosts(s.docs.map((d) => ({ id: d.id, ...d.data() })));
                                      });
                                          const u3 = myUid ? onSnapshot(doc(db, 'users', myUid), (s) => { if (s.exists()) setMe(s.data()); }) : () => {};
                                              return () => { u1(); u2(); u3(); };
                                                }, [id, myUid]);

                                                  const isFollowing = Array.isArray(profile?.followers) && profile.followers.includes(myUid);
                                                    const isRequested = Array.isArray(profile?.followRequests) && profile.followRequests.includes(myUid);
                                                      const isCloseFriend = Array.isArray(me?.closeFriends) && me.closeFriends.includes(id);
                                                        const canView = !profile?.isPrivate || isFollowing || myUid === id;

                                                          const handleFollowAction = async () => {
                                                              if (!myUid || !id || myUid === id) return;
                                                                  if (isFollowing) {
                                                                        await updateDoc(doc(db, 'users', id), { followers: arrayRemove(myUid) });
                                                                              await updateDoc(doc(db, 'users', myUid), { following: arrayRemove(id) });
                                                                                  } else if (profile?.isPrivate) {
                                                                                        if (isRequested) {
                                                                                                await updateDoc(doc(db, 'users', id), { followRequests: arrayRemove(myUid) });
                                                                                                      } else {
                                                                                                              await updateDoc(doc(db, 'users', id), { followRequests: arrayUnion(myUid) });
                                                                                                                      const mySnap = await getDoc(doc(db, 'users', myUid));
                                                                                                                              await addDoc(collection(db, 'notifications'), {
                                                                                                                                        toUid: id, fromUid: myUid, fromUsername: mySnap.data()?.username || 'user',
                                                                                                                                                  type: 'follow_request', message: 'requested to follow you.', read: false, createdAt: serverTimestamp(),
                                                                                                                                                          });
                                                                                                                                                                }
                                                                                                                                                                    } else {
                                                                                                                                                                          await updateDoc(doc(db, 'users', id), { followers: arrayUnion(myUid) });
                                                                                                                                                                                await updateDoc(doc(db, 'users', myUid), { following: arrayUnion(id) });
                                                                                                                                                                                      const mySnap = await getDoc(doc(db, 'users', myUid));
                                                                                                                                                                                            await addDoc(collection(db, 'notifications'), {
                                                                                                                                                                                                    toUid: id, fromUid: myUid, fromUsername: mySnap.data()?.username || 'user',
                                                                                                                                                                                                            type: 'follow', message: 'started following you.', read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                  });
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                        };

                                                                                                                                                                                                                          const toggleCloseFriend = async () => {
                                                                                                                                                                                                                              if (!myUid || !id || myUid === id) return;
                                                                                                                                                                                                                                  await updateDoc(doc(db, 'users', myUid), {
                                                                                                                                                                                                                                        closeFriends: isCloseFriend ? arrayRemove(id) : arrayUnion(id),
                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                const reportUser = () => {
                                                                                                                                                                                                                                                    Alert.alert('Report User', `Report @${profile?.username}?`, [
                                                                                                                                                                                                                                                          { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                        text: 'Report',
                                                                                                                                                                                                                                                                                style: 'destructive',
                                                                                                                                                                                                                                                                                        onPress: async () => {
                                                                                                                                                                                                                                                                                                  await addDoc(collection(db, 'reports'), { targetUid: id, type: 'user', reportedBy: myUid, status: 'pending', createdAt: serverTimestamp() });
                                                                                                                                                                                                                                                                                                            Alert.alert('Reported', 'Thank you. Our team will review this account.');
                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                              ]);
                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                  if (!profile) {
                                                                                                                                                                                                                                                                                                                                      return <View style={[styles.center, { backgroundColor: c.background }]}><Text style={{ color: c.muted }}>Loading...</Text></View>;
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                          const followLabel = isFollowing ? 'Following' : isRequested ? 'Requested' : profile.isPrivate ? 'Request' : 'Follow';

                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                <View style={[styles.container, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                      <View style={styles.topBar}>
                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => router.back()}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                      <Text style={[styles.topTitle, { color: c.text, flex: 1 }]}>@{profile.username}</Text>
                                                                                                                                                                                                                                                                                                                                                                              {myUid !== id && <TouchableOpacity onPress={reportUser}><Ionicons name="flag-outline" size={20} color="#EF4444" /></TouchableOpacity>}
                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                          <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                  data={canView ? posts : []}
                                                                                                                                                                                                                                                                                                                                                                                                          numColumns={3}
                                                                                                                                                                                                                                                                                                                                                                                                                  keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                                                                                                                                                                          ListHeaderComponent={
                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={{ padding: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={styles.infoRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                              {profile.avatar ? <Image source={{ uri: profile.avatar }} style={styles.avatar} /> : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[styles.avatar, { backgroundColor: BRAND, justifyContent: 'center', alignItems: 'center' }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={styles.avatarText}>{(profile.username || 'U')[0].toUpperCase()}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.statsRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.statBox}><Text style={[styles.statNum, { color: c.text }]}>{posts.length}</Text><Text style={{ color: c.muted, fontSize: 12 }}>Posts</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.statBox}><Text style={[styles.statNum, { color: c.text }]}>{profile.followers?.length || 0}</Text><Text style={{ color: c.muted, fontSize: 12 }}>Followers</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.statBox}><Text style={[styles.statNum, { color: c.text }]}>{profile.following?.length || 0}</Text><Text style={{ color: c.muted, fontSize: 12 }}>Following</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={[styles.fullName, { color: c.text }]}>{profile.fullName || ''}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {!!profile.bio && <Text style={{ color: c.text, marginTop: 2 }}>{profile.bio}</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {!!profile.website && <TouchableOpacity onPress={() => Linking.openURL(profile.website)}><Text style={{ color: BRAND, marginTop: 2 }}>{profile.website}</Text></TouchableOpacity>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {myUid !== id && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={styles.btnRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={[styles.btn, { backgroundColor: isFollowing || isRequested ? c.input : BRAND }]} onPress={handleFollowAction}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={{ color: isFollowing || isRequested ? c.text : '#fff', fontWeight: '700' }}>{followLabel}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={[styles.btn, { backgroundColor: c.input }]} onPress={() => router.navigate({ pathname: '/messages' as any, params: { uid: id, name: profile.username } })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ color: c.text, fontWeight: '700' }}>Message</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity style={[styles.cfBtn, { backgroundColor: isCloseFriend ? '#10B981' : c.input }]} onPress={toggleCloseFriend}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Ionicons name="star" size={18} color={isCloseFriend ? '#fff' : '#10B981'} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {!canView && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.lockBox}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Ionicons name="lock-closed-outline" size={38} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ color: c.text, fontWeight: '700', marginTop: 8 }}>This Account is Private</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ color: c.muted, fontSize: 13 }}>Follow this account to see their posts.</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderItem={({ item }) => <Image source={{ uri: item.mediaUrl || item.media?.[0] }} style={styles.gridImg} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                container: { flex: 1, paddingTop: 46 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    topBar: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, gap: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      topTitle: { fontSize: 17, fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        infoRow: { flexDirection: 'row', alignItems: 'center', gap: 18 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          avatar: { width: 74, height: 74, borderRadius: 37 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            avatarText: { color: '#fff', fontSize: 22, fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              statsRow: { flex: 1, flexDirection: 'row', justifyContent: 'space-around' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statBox: { alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  statNum: { fontSize: 16, fontWeight: '800' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fullName: { fontWeight: '700', marginTop: 10, fontSize: 15 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      btnRow: { flexDirection: 'row', gap: 8, marginTop: 14 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btn: { flex: 1, padding: 10, borderRadius: 10, alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cfBtn: { padding: 10, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            lockBox: { alignItems: 'center', marginTop: 40, gap: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              gridImg: { width: W, height: W, margin: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              